// Decides what to do with every Telegram update: password gate, commands, prompts, ratings.
const cfg = $('Config').first().json;
const upd = $('Telegram Trigger').first().json;
const sd = $getWorkflowStaticData('global');       // persists between PUBLISHED executions
const users = sd.users || {};
const attempts = sd.attempts || {};
const support = cfg.supportContact;
const maxAttempts = Number(cfg.maxAttempts) || 5;
const lockoutMs = (Number(cfg.lockoutMinutes) || 10) * 60000;
const supportId = String(cfg.supportChatId || '').trim();

// ───────── password rotation ─────────
// Every login is tied to the password VERSION that was active when the user typed it. Whenever the
// password in the Config node changes, the version goes up and every earlier login stops working:
// each user must type the NEW password. A password that was used before is refused (blockPasswordReuse).
// Only a salted SHA-256 fingerprint of the password is kept in the saved state, never the password itself.
const utf8 = (s) => {
  const o = [];
  for (const ch of String(s)) {
    const c = ch.codePointAt(0);
    if (c < 0x80) o.push(c);
    else if (c < 0x800) o.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) o.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else o.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return o;
};
const sha256 = (str) => {
  const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  const H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const m = utf8(str);
  const bits = m.length * 8;
  m.push(0x80);
  while (m.length % 64 !== 56) m.push(0);
  const hi = Math.floor(bits / 0x100000000), lo = bits >>> 0;
  m.push((hi >>> 24) & 255, (hi >>> 16) & 255, (hi >>> 8) & 255, hi & 255, (lo >>> 24) & 255, (lo >>> 16) & 255, (lo >>> 8) & 255, lo & 255);
  const rr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let i = 0; i < m.length; i += 64) {
    const w = new Array(64);
    for (let j = 0; j < 16; j++) w[j] = ((m[i + 4 * j] << 24) | (m[i + 4 * j + 1] << 16) | (m[i + 4 * j + 2] << 8) | m[i + 4 * j + 3]) | 0;
    for (let j = 16; j < 64; j++) {
      const s0 = rr(w[j - 15], 7) ^ rr(w[j - 15], 18) ^ (w[j - 15] >>> 3);
      const s1 = rr(w[j - 2], 17) ^ rr(w[j - 2], 19) ^ (w[j - 2] >>> 10);
      w[j] = (w[j - 16] + s0 + w[j - 7] + s1) | 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let j = 0; j < 64; j++) {
      const t1 = (h + (rr(e, 6) ^ rr(e, 11) ^ rr(e, 25)) + ((e & f) ^ (~e & g)) + K[j] + w[j]) | 0;
      const t2 = ((rr(a, 2) ^ rr(a, 13) ^ rr(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0;
    H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
  }
  return H.map((x) => (x >>> 0).toString(16).padStart(8, '0')).join('');
};

const pwText = String(cfg.password ?? '');
const pwEmpty = !pwText.trim();
const blockReuse = !(cfg.blockPasswordReuse === false || String(cfg.blockPasswordReuse).toLowerCase() === 'false');
if (!sd.pw) sd.pw = { salt: Math.random().toString(16).slice(2) + Math.random().toString(16).slice(2), fp: null, ver: 0, since: null, history: [], reused: false, notified: true, log: [] };
const pw = sd.pw;
const pwFp = sha256(pw.salt + '|' + pwText);
let pendingNote = null;                                   // sent to support once, with the next reply
if (pw.fp !== pwFp) {
  const firstRun = !pw.fp;
  if (!firstRun) pw.history = [...(pw.history || []), pw.fp].slice(-50);
  pw.reused = !firstRun && !pwEmpty && pw.history.includes(pwFp);
  pw.fp = pwFp;
  pw.ver = (pw.ver || 0) + 1;                             // a new version logs everyone out, even when going back to an old password
  pw.since = new Date().toISOString();
  pw.invalidated = Object.keys(sd.users || {}).length;
  pw.notified = false;
  pw.log = [...(pw.log || []), { at: pw.since, ver: pw.ver, reused: pw.reused, usersLoggedOut: pw.invalidated }].slice(-10);
}
const pwBlocked = pwEmpty ? 'empty' : (blockReuse && pw.reused ? 'reused' : '');
if (!pw.notified && cfg.supportChatId) {
  pendingNote = pwBlocked === 'reused'
    ? '⛔ The password in Config was used before. Access is paused for everyone until you set a NEW password (blockPasswordReuse is on).'
    : pwBlocked === 'empty'
      ? '⛔ No password is set in Config. Access is paused until you set one.'
      : `🔑 Password change detected (version ${pw.ver}).\n${pw.invalidated} user(s) were logged out and must type the new password before they can use the bot.`;
}

const cb = upd.callback_query;
const msg = upd.message;
const from = (cb ? cb.from : (msg && msg.from)) || {};
const chat = cb ? (cb.message && cb.message.chat) : (msg && msg.chat);

// Private chats only, so the password is never typed in a group.
if (!chat || chat.type !== 'private' || from.is_bot) {
  return [{ json: { action: 'ignore' } }];
}

const chatId = chat.id;
const userId = from.id;
const username = from.username ? '@' + from.username : (from.first_name || String(userId));
const base = {
  chatId, userId, username,
  handle: from.username ? '@' + from.username : '',
  firstName: from.first_name || '',
  lastName: from.last_name || '',
  lang: from.language_code || '',
};
const reply = (text, extra = {}) => {
  const note = (pendingNote && !extra.supportText) ? { supportChatId: String(cfg.supportChatId).trim(), supportText: pendingNote } : {};
  if (note.supportText) { pw.notified = true; pendingNote = null; }
  return [{ json: { ...base, action: 'reply', replyText: text, ...note, ...extra } }];
};
// A login only counts if it was made under the CURRENT password version.
const rec = users[userId];
const stale = !!rec && rec.pwVer !== pw.ver;          // had access under an older password
const authorized = !!rec && !stale && !pwBlocked;

// /myid works for everyone (even before login) so support can find their numeric ID.
const rawText = ((msg && msg.text) || '').trim();
if (!cb && /^\/myid(@\w+)?$/i.test(rawText)) {
  return reply(`🆔 Your Telegram ID: ${userId}\nUsername: ${username}`);
}

const HELP =
  'Send me a description of the image you want and I will generate it.\n\n' +
  '⏱ One image takes about 2 minutes. The GPU makes 1 image at a time, so extra requests wait in a queue.\n\n' +
  'Commands:\n/status - queue and GPU status\n/review <text> - add a comment to your last rating\n/skip - skip the comment\n/myid - show your Telegram ID\n/help - show this message';

// ───────── button taps (star ratings) ─────────
if (cb) {
  const m = /^rate:([A-Za-z0-9]+):([1-5])$/.exec(cb.data || '');
  if (!authorized || !m) return [{ json: { ...base, action: 'ignore' } }];
  return [{ json: { ...base, action: 'rate', jobId: m[1], rating: Number(m[2]), callbackId: cb.id, messageId: cb.message.message_id } }];
}

const text = ((msg && msg.text) || '').trim();

// ───────── not logged in: password gate ─────────
if (!authorized) {
  const now = Date.now();
  const a = attempts[userId] || { count: 0, lockedUntil: 0 };
  const del = msg ? { deleteMessage: true, deleteMessageId: msg.message_id } : {};

  // Access is paused until the administrator sets a new, unused password.
  if (pwBlocked) {
    return reply(pwBlocked === 'reused'
      ? `⛔ Access is paused: the administrator must set a NEW password. Please contact support: ${support}`
      : `⛔ Access is paused: no password is configured. Please contact support: ${support}`, del);
  }
  if (a.lockedUntil && a.lockedUntil > now) {
    const mins = Math.ceil((a.lockedUntil - now) / 60000);
    return reply(`⛔ Too many wrong attempts. Please try again in ${mins} min, or contact support: ${support}`, del);
  }
  // Step 1: always ask for the password first (this is not counted as an attempt).
  if (!(sd.awaiting && sd.awaiting[userId]) || text === '/start') {
    if (!sd.awaiting) sd.awaiting = {};
    sd.awaiting[userId] = true;
    // A message other than /start may already be the password: do not leave it in the chat.
    return reply(stale
      ? '🔑 The access password was changed.\n\nPlease type the NEW password to continue. The old password no longer works.'
      : '🔒 Welcome! This bot is private.\n\nPlease type your access password to continue.',
      (msg && text && text !== '/start') ? del : {});
  }
  if (!text) return reply('Please type your access password as a text message.');
  // Step 2: check the password the user typed.
  if (text === String(cfg.password)) {
    if (!sd.users) sd.users = {};
    const prev = sd.users[userId] || {};
    sd.users[userId] = {
      username, name: from.first_name || '', chatId,
      firstAccessAt: prev.firstAccessAt || prev.authorizedAt || new Date().toISOString(),
      authorizedAt: new Date().toISOString(),
      pwVer: pw.ver,                                // valid only for this password version
      reviews: prev.reviews || [],
    };
    if (sd.attempts && sd.attempts[userId]) delete sd.attempts[userId];
    if (sd.awaiting) delete sd.awaiting[userId];
    return reply('✅ Access granted!\n\n' + HELP, del);
  }
  const count = (a.count || 0) + 1;
  if (!sd.attempts) sd.attempts = {};
  if (count >= maxAttempts) {
    sd.attempts[userId] = { count: 0, lockedUntil: now + lockoutMs };
    return reply(`⛔ Too many wrong attempts. Please try again in ${Math.ceil(lockoutMs / 60000)} min, or contact support: ${support}`, del);
  }
  sd.attempts[userId] = { count, lockedUntil: 0 };
  const left = maxAttempts - count;
  return reply(`❌ Wrong password (${left} attempt${left === 1 ? '' : 's'} left).\nPlease contact support: ${support}`, del);
}

// ───────── logged in ─────────
if (!text) return reply('Please send a text description of the image you want.');

const u = sd.users[userId];
if (u.pendingComment && u.pendingComment.until < Date.now()) delete u.pendingComment;

// Saves a comment on the rated image and builds the copy that goes to support (with the user ID).
const saveComment = (comment) => {
  const list = u.reviews || [];
  const pc = u.pendingComment;
  const rv = (pc && list.find(x => x.jobId === pc.jobId)) || list[list.length - 1];
  if (!rv) return null;
  rv.comment = comment.slice(0, 1000);
  delete u.pendingComment;
  return rv;
};
// Sender details that go to support with every comment.
const senderInfo = () => (
  `👤 User ID: ${userId}\n` +
  `Username: ${base.handle || '(no username)'}\n` +
  `Name: ${[base.firstName, base.lastName].filter(Boolean).join(' ') || 'n/a'}\n` +
  `Chat ID: ${chatId}\n` +
  `Language: ${base.lang || 'n/a'}\n` +
  `Access since: ${u.authorizedAt || 'n/a'}`
);
const commentReply = (rv) => reply(
  '🙏 Thank you! Your comment was sent to our support team.',
  supportId ? {
    supportChatId: supportId,
    supportText:
      `💬 New comment\n${senderInfo()}\n\n` +
      `Rating: ${'⭐'.repeat(rv.rating)} (${rv.rating}/5)\nComment: ${rv.comment}\n\n` +
      `Prompt: ${String(rv.prompt || 'n/a').slice(0, 200)}\nSeed: ${rv.seed ?? 'n/a'}\nJob: ${rv.jobId}`,
  } : {},
);

const [cmd, ...rest] = text.split(/\s+/);
const arg = rest.join(' ').trim();

// A rating was just given (within 10 min): the next plain message is the comment.
if (u.pendingComment && !text.startsWith('/')) {
  const rv = saveComment(text);
  if (rv) return commentReply(rv);
}

if (cmd === '/start' || cmd === '/help') return reply(HELP);
if (cmd === '/status') return [{ json: { ...base, action: 'status' } }];

if (cmd === '/skip') {
  const had = !!u.pendingComment;
  delete u.pendingComment;
  return reply(had ? 'OK, no comment. Send me your next image description whenever you like.' : 'Nothing to skip. Send me an image description to start.');
}

if (cmd === '/review') {
  if (!arg) return reply('Usage: /review <your comment about your last image>');
  const rv = saveComment(arg);
  if (!rv) return reply('Please rate an image first with the star buttons, then add your comment with /review <text>.');
  return commentReply(rv);
}

if (cmd === '/reviews' && supportId && String(userId) === supportId) {
  const all = [];
  for (const [id, u] of Object.entries(users)) {
    for (const r of (u.reviews || [])) all.push({ ...r, who: u.username || id });
  }
  all.sort((x, y) => String(y.at || '').localeCompare(String(x.at || '')));
  const lines = all.slice(0, 15).map(r =>
    `${r.who}: ${'⭐'.repeat(r.rating)} (${r.rating}/5)` +
    (r.comment ? `\n   "${r.comment}"` : '') +
    (r.prompt ? `\n   prompt: ${String(r.prompt).slice(0, 80)}` : ''));
  const activeUsers = Object.values(users).filter(x => x.pwVer === pw.ver).length;
  return reply(`👥 ${activeUsers} users with access (${Object.keys(users).length} ever) · ${all.length} reviews\n\n` + (lines.join('\n\n') || 'No reviews yet.'));
}

if (cmd === '/errors' && supportId && String(userId) === supportId) {
  const log = (sd.errorLog || []).slice(-8).reverse();
  if (!log.length) return reply('✅ No delivery errors recorded.');
  return reply(`🛑 Last ${log.length} delivery errors\n\n` + log.map(e =>
    `${e.at}\n${e.failedAfter} · user ${e.userId} · job ${e.jobId}\n${String(e.error).slice(0, 250)}`).join('\n\n'));
}

if (cmd.startsWith('/')) return reply('Unknown command. Send /help to see what I can do.');

if (text.length > 1500) return reply('That prompt is too long. Please keep it under 1500 characters.');

return [{ json: { ...base, action: 'generate', prompt: text } }];

// Turns the server's job status into the Telegram progress message.
const cfg = $('Config').first().json;
const route = $('Auth & route').first().json;
const j = $input.first().json || {};
const run = $runIndex;

const fmt = (s) => {
  s = Math.max(0, Math.round(Number(s) || 0));
  const m = Math.floor(s / 60), r = s % 60;
  return m ? `${m} min ${String(r).padStart(2, '0')} s` : `${r} s`;
};
const bar = (p) => {
  p = Math.max(0, Math.min(100, Math.round(Number(p) || 0)));
  const n = 12, f = Math.round((p / 100) * n);
  return '█'.repeat(f) + '░'.repeat(n - f) + ` ${p}%`;
};

const status = j.status || 'unknown';
const finished = ['done', 'error', 'not_found'].includes(status) || run > 300;
const gpu = `🖥 GPU: ${j.max_concurrent || 1} image at a time · ${j.queue_length ?? 0} waiting in queue`;
const intro = run === 0 ? '📥 Request received!\n\n' : '';

let text;
let caption = '';
if (status === 'done') {
  // This bar is for GENERATING only; sending the picture has its own message and bar.
  text = `✅ Image generated in ${fmt(j.total_seconds)}!\n\n${bar(100)}\n📤 Sending progress is shown in the next message.`;
  caption = `🖼 Done in ${fmt(j.total_seconds)} · seed ${j.seed}`;
} else if (finished) {
  text = `❌ Sorry, something went wrong while generating your image.\nPlease try again, or contact support: ${cfg.supportContact}`;
} else if (status === 'queued') {
  text = `${intro}🕒 You are in the queue\n\n${bar(0)}\n👥 Requests ahead of you: ${j.ahead ?? 0}\n⏱ Estimated wait: about ${fmt(j.eta_seconds)}\n${gpu}`;
} else if (status === 'running') {
  text = `${intro}🎨 ${j.stage_label || 'Working'}\n\n${bar(j.progress_percent)}\n⏱ About ${fmt(j.eta_seconds)} left\n${gpu}`;
} else {
  text = '⏳ Still working…';
}

let messageId = null;
if (run > 0) {
  try {
    const sent = $('Send progress message').first().json;
    messageId = (sent.result && sent.result.message_id) ?? sent.message_id ?? null;
  } catch (e) { /* first message not available */ }
}

let jobId = j.job_id;
if (!jobId) jobId = $('Submit job').first().json.job_id;

return [{ json: { first: run === 0, finished, status, text, caption, jobId, chatId: route.chatId, messageId, totalText: fmt(j.total_seconds) } }];

// Stores the star rating in the same user record that holds the username and access status.
const r = $('Auth & route').first().json;
const cfg = $('Config').first().json;
const info = $input.first().json || {};
const sd = $getWorkflowStaticData('global');
const supportId = String(cfg.supportChatId || '').trim();

const rec = sd.users && sd.users[r.userId];
// Access only counts under the CURRENT password version (see Auth & route).
const u = rec && sd.pw && rec.pwVer === sd.pw.ver ? rec : null;
if (!u) {
  return [{ json: { chatId: r.chatId, messageId: r.messageId, callbackId: r.callbackId, text: 'Please send the access password first.', notifySupport: false } }];
}
if (!u.reviews) u.reviews = [];

const entry = {
  jobId: r.jobId,
  rating: r.rating,
  at: new Date().toISOString(),
  prompt: info.prompt || null,
  seed: info.seed ?? null,
  seconds: info.total_seconds ?? null,
};
const idx = u.reviews.findIndex(x => x.jobId === r.jobId);
const updated = idx >= 0;
if (updated) {
  if (u.reviews[idx].comment) entry.comment = u.reviews[idx].comment;
  u.reviews[idx] = entry;
} else {
  u.reviews.push(entry);
}
if (u.reviews.length > 200) u.reviews = u.reviews.slice(-200);

// The next plain message from this user (within 10 minutes) is taken as the comment.
u.pendingComment = { jobId: r.jobId, until: Date.now() + 10 * 60000 };

const stars = '⭐'.repeat(r.rating);
const text = `${updated ? 'Rating updated' : 'Thanks for rating'}! ${stars} (${r.rating}/5)\n\n💬 Want to tell us more? Type your comment now and I will send it to our support team (or send /skip).`;
const rated = u.reviews.map(x => x.rating).filter(Number.isFinite);
const avg = rated.length ? (rated.reduce((a, b) => a + b, 0) / rated.length).toFixed(1) : 'n/a';
const supportText =
  `${updated ? '🔄 Rating updated' : '⭐ New rating'}\n` +
  `👤 User ID: ${r.userId}\n` +
  `Username: ${r.handle || '(no username)'}\n` +
  `Name: ${[r.firstName, r.lastName].filter(Boolean).join(' ') || 'n/a'}\n` +
  `Chat ID: ${r.chatId}\n` +
  `Language: ${r.lang || 'n/a'}\n` +
  `Access since: ${u.authorizedAt || 'n/a'}\n` +
  `Ratings from this user: ${rated.length} (average ${avg}/5)\n\n` +
  `Rating: ${stars} (${r.rating}/5)\n` +
  `Prompt: ${String(info.prompt || 'n/a').slice(0, 200)}\n` +
  `Seed: ${info.seed ?? 'n/a'}\n` +
  `Generation time: ${info.total_seconds != null ? Math.round(info.total_seconds) + ' s' : 'n/a'}\n` +
  `Job: ${r.jobId}`;

return [{ json: {
  chatId: r.chatId, messageId: r.messageId, callbackId: r.callbackId, text,
  notifySupport: !!supportId, supportChatId: supportId, supportText,
} }];

// Builds a readable error log for whichever node failed (Download image or Send image).
const route = $('Auth & route').first().json;
const cfg = $('Config').first().json;
let fp = {};
try { fp = $('Format progress').first().json; } catch (e) { /* not available */ }
const j = $input.first().json || {};

let detail;
try {
  const raw = j.error !== undefined ? j.error : j;
  detail = typeof raw === 'string' ? raw : JSON.stringify(raw, null, 2);
} catch (e) {
  detail = String(j.error || e);
}
detail = String(detail || 'no error text');

const step = $prevNode.name;   // "Download image" or "Send image"

// First matching pattern wins.
const hints = [
  [/too big|too large|entity too large|PHOTO_SAVE_FILE_INVALID|IMAGE_PROCESS_FAILED/i,
    'The image is probably over Telegram photo limits (10 MB, or width+height above 10000 px). Save it smaller or as JPEG on the server, or change Send image to sendDocument.'],
  [/PHOTO_INVALID_DIMENSIONS/i,
    'sendPhoto does not accept these dimensions (width+height must be 10000 or less, ratio 20 or less). Resize the image or use sendDocument.'],
  [/binary|no data/i,
    'Send image did not receive the file. Check that Download image is connected directly to Send image and outputs the binary property "data".'],
  [/ECONNREFUSED|ENOTFOUND|EAI_AGAIN|ETIMEDOUT|ECONNRESET|ESOCKETTIMEDOUT/i,
    'Could not reach the image server (or Telegram). Check serverUrl, that flux_queue_server.py is running, and that host.docker.internal works from n8n.'],
  [/timeout|timed out/i,
    'The request timed out. Increase the timeout on Download image / Send image, or check the connection speed.'],
  [/403|blocked|chat not found|deactivated/i,
    'Telegram refused delivery: the user may have blocked the bot, or the chat ID is wrong.'],
  [/429|too many requests|retry after/i,
    'Telegram rate limit reached. Wait a moment and try again.'],
  [/404|not found/i,
    'The server returned 404: the image for this job does not exist (check the /jobs/{id}/image route and the output folder).'],
];
const hint = (hints.find(([re]) => re.test(detail)) || [null, 'No known pattern. See the full error text.'])[1];

const jobId = String(fp.jobId || 'unknown');
const entry = {
  at: new Date().toISOString(),
  failedAfter: step,
  userId: route.userId,
  username: route.username,
  jobId,
  error: detail.slice(0, 1500),
  hint,
};

// 1) n8n server log   2) last 20 errors kept in workflow static data (shown by /errors)
